import React from 'react';
import styled from 'styled-components';

const ExperienceSection = styled.section`
  max-width: 700px;
  margin: 0 auto;
  padding: 3rem 1.5rem;
  color: #fff;
`;

const Heading = styled.h2`
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 2rem;
  color: #fff;
`;

const Timeline = styled.ul`
  list-style: none;
  padding: 0;
  margin: 0;
  border-left: 2px solid #222;
`;

const Item = styled.li`
  margin-bottom: 2.5rem;
  padding-left: 1.5rem;
  position: relative;

  &::before {
    content: '';
    position: absolute;
    left: -9px;
    top: 0.5rem;
    width: 14px;
    height: 14px;
    background: #fff;
    border-radius: 50%;
    border: 2px solid #000;
    box-shadow: 0 0 0 3px #000;
  }
`;

const Role = styled.h3`
  font-size: 1.15rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 0.2rem;
`;

const Place = styled.div`
  color: #aaa;
  font-size: 1rem;
  margin-bottom: 0.2rem;
`;

const Period = styled.div`
  color: #aaa;
  font-size: 0.95rem;
  margin-bottom: 0.5rem;
`;

const Description = styled.p`
  color: #aaa;
  font-size: 1.05rem;
`;

const experience = [
  {
    role: 'Frontend Developer',
    place: 'Acme Corp',
    period: '2023 – Present',
    description: 'Building and optimizing scalable web applications with React and modern JS.'
  },
  {
    role: 'BSc Computer Science',
    place: 'University of Example',
    period: '2019 – 2022',
    description: 'Focused on software engineering, UI/UX, and web technologies.'
  }
];

const Experience = () => (
  <ExperienceSection id="experience">
    <Heading>Experience & Education</Heading>
    <Timeline>
      {experience.map(({ role, place, period, description }) => (
        <Item key={role + place}>
          <Role>{role}</Role>
          <Place>{place}</Place>
          <Period>{period}</Period>
          <Description>{description}</Description>
        </Item>
      ))}
    </Timeline>
  </ExperienceSection>
);

export default Experience;
